/* ---------- Pages ---------- */
function Testimonials({ setPage }) {
  const [index, setIndex] = useState(0);
  const t = TESTIMONIALS[index];

  function prev() {
    setIndex((index - 1 + TESTIMONIALS.length) % TESTIMONIALS.length);
  }
  function next() {
    setIndex((index + 1) % TESTIMONIALS.length);
  }

  return (
    <section className="max-w-5xl mx-auto px-5 pb-16">
      <div className="flex items-baseline justify-between mb-5">
        <h2 className="serif text-2xl font-bold" style={{ color: NAVY }}>What people are saying</h2>
        {setPage && (
          <button onClick={() => setPage("feedback")} className="sans text-sm font-semibold" style={{ color: GREEN_DARK }}>
            Share your feedback →
          </button>
        )}
      </div>
      <div className="rounded-2xl border overflow-hidden" style={{ borderColor: "#E7E2D4", backgroundColor: "#FBF9F2" }}>
        <div style={{ height: 4, background: `linear-gradient(90deg, ${GREEN} 0%, ${BLUE} 50%, ${GOLD} 100%)` }} />
        <div className="p-8">
        <div className="flex gap-1 mb-4">
          {Array.from({ length: t.rating }).map((_, i) => (
            <Star key={i} size={16} fill={GOLD} style={{ color: GOLD }} />
          ))}
        </div>
        <p className="sans text-lg leading-relaxed mb-6" style={{ color: "#333" }}>&ldquo;{t.text}&rdquo;</p>
        <div className="sans font-semibold text-sm" style={{ color: NAVY }}>{t.name}</div>

        <div className="flex items-center gap-3 mt-7">
          <button onClick={prev} aria-label="Previous review" className="w-9 h-9 rounded-full border flex items-center justify-center hover-lift press" style={{ borderColor: "#E7E2D4" }}>
            <ChevronLeft size={16} />
          </button>
          <div className="flex gap-1.5">
            {TESTIMONIALS.map((_, i) => (
              <button
                key={i}
                onClick={() => setIndex(i)}
                aria-label={`Go to review ${i + 1}`}
                className="rounded-full press"
                style={{ width: 7, height: 7, backgroundColor: i === index ? GREEN : "#E0DCCB" }}
              />
            ))}
          </div>
          <button onClick={next} aria-label="Next review" className="w-9 h-9 rounded-full border flex items-center justify-center hover-lift press" style={{ borderColor: "#E7E2D4" }}>
            <ChevronRight size={16} />
          </button>
        </div>
        </div>
      </div>
    </section>
  );
}

